            // Ato 11
            gato_mato_garras: 'garras', gato_mato_salto: 'felino',
            mariposa_po: 'mariposa', mariposa_voo: 'mariposa',
            quati_garras: 'garras', quati_bote: 'bote',
            sucuarana_garra: 'garras', sucuarana_salto: 'felino',

            // Ato 12
