    const PA_KEY = 'curupira_chuva_flechas';
    const _sleep = (ms) => new Promise(r => setTimeout(r, ms));
    const _corrompido = (idx) =>
        Array.isArray(window._corruptedTiles) && window._corruptedTiles.includes(idx);

    const st = {
        ativo: false,
        tiles: [],
        overlay: null,
        overlayTimer: null,
        resolve: null,
        captureHandler: null,
        preCapture: null,
    };

    // ─────────────────────────────────────────────────────────────
    // LOCALIZAR BOTÃO
